
CREATE TABLE "QUICKSQLORDER" ("ID" NUMBER(10) IDENTITY(1,1) NOT NULL, "CUSTOMERNAME" VARCHAR2(64 CHAR) NULL, "CUSTOMERID" NUMBER(10) NOT NULL, "AMOUNT" NUMBER(18,4) NOT NULL, "STATE" NUMBER(10) NOT NULL, "CREATEDAT" TIMESTAMP(3) NOT NULL, "PAIDAT" TIMESTAMP(3) NULL, "NOTE" CLOB NULL, CONSTRAINT "PK_QUICKSQLORDER" PRIMARY KEY ("ID")) ; CREATE INDEX "IX_QUICKSQLORDER_CREATEDAT" ON "QUICKSQLORDER" ( "CREATEDAT" ASC )
